H.background();
const W = H.W, Ht = H.H;
const ni = Math.round(P.ni);
const nf = Math.round(P.nf);
const E = n => -13.6 / (n * n);
const nMax = 5;
const topY = 90, botY = Ht - 70;
const yOf = n => {
  const En = E(n);
  return botY + (En - E(1)) / (0 - E(1)) * (topY - botY);
};
H.text("Hydrogen energy levels: E_n = -13.6 / n^2 eV", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Photon energy = E_i - E_f for the marked transition", 24, 52, { color: H.colors.sub, size: 13 });
for (let n = 1; n <= nMax; n++) {
  const y = yOf(n);
  H.line(120, y, 380, y, { color: H.colors.grid, width: 2 });
  H.text("n=" + n, 90, y, { color: H.colors.sub, size: 12, align: "right", baseline: "middle" });
  H.text(E(n).toFixed(2) + " eV", 392, y, { color: H.colors.sub, size: 11, baseline: "middle" });
}
const yi = yOf(ni), yf = yOf(nf);
const dE = E(ni) - E(nf);
const ax = 250;
H.arrow(ax, yi, ax, yf, { color: dE > 0 ? H.colors.warn : H.colors.accent, width: 3 });
const emit = ni > nf;
const photonE = Math.abs(dE);
const lamNm = photonE > 0.001 ? 1239.84 / photonE : 0;
if (emit && photonE > 0.001) {
  const frac = (t % 1.5) / 1.5;
  const wx = 470 + frac * 340;
  const wy = (yi + yf) / 2;
  for (let i = 0; i < 60; i++) {
    const xx = wx - i * 4;
    if (xx < 460) break;
    const yy = wy + 16 * Math.sin(i * 0.5 + t * 6);
    H.circle(xx, yy, 1.6, { fill: H.colors.yellow });
  }
  H.circle(wx, wy, 5, { fill: H.colors.yellow });
}
H.text((emit ? "Emission" : "Absorption") + ": " + ni + " -> " + nf, 470, 90, { color: H.colors.ink, size: 14, weight: 700 });
H.text("E_photon = |E_i - E_f| = " + photonE.toFixed(2) + " eV", 470, 116, { color: H.colors.accent2, size: 13 });
H.text("lambda = " + (lamNm > 0 ? lamNm.toFixed(0) : "-") + " nm", 470, 138, { color: H.colors.sub, size: 13 });
